import hashlib

def check_login(username, password):
    # Hardcoded user database for CTF challenge
    users = {
        'admin': 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855',  # hash of 'password123'
        'user1': '5e884898da28047151d0e56f8dc62927510d5f32aeab7e965d1d52d5985edf8b',  # hash of 'qwerty'
        'moderator': '8d969eef6ecad3c29a3a873fba8fe814e25c91d1524c42d39669d0e4fd8b674b'  # hash of 'test'
    }

    if username not in users:
        return False

    provided_hash = hashlib.sha256(password.encode()).hexdigest()
    return provided_hash == users[username]

def login_user(username, password):
    if check_login(username, password):
        return {'status': 'success', 'token': f'{username}_token_{password}'}
    else:
        return {'status': 'failed', 'message': 'Invalid credentials'}

# Test the challenge
if __name__ == '__main__':
    print(login_user('admin', 'password123'))
    print(login_user('admin', 'wrong'))
